import React from 'react';

const Contact = () => {
  const handleSubmit = async (e) => {
    e.preventDefault();
    const formData = new FormData(e.target); // Use FormData for PHP $_POST compatibility

    try {
      const response = await fetch('contact.php', {
        method: 'POST',
        body: formData
      });

      if (response.ok) {
        // Removed unused 'result' variable to fix ESLint warning
        alert('Message sent successfully!'); // Customize based on PHP response if needed
        e.target.reset(); // Clear the form
      } else {
        alert('Failed to send message. Please try again.');
      }
    } catch (error) {
      console.error('Error:', error);
      alert('An error occurred. Please try again.');
    }
  };

  return (
    <section id="contact">
      <h2 className="section-title">Contact Me</h2>
      <div className="contact-wrapper">
        <div className="contact-form">
          <form id="contact-form" onSubmit={handleSubmit}>
            <input type="text" name="name" placeholder="Your Name" required />
            <input type="email" name="email" placeholder="Your Email" required />
            <textarea name="message" placeholder="Your Message" rows="6" required></textarea>
            <button type="submit" className="btn-submit">Send Message</button>
          </form>
        </div>
        <div className="contact-info">
          <h3>Get in Touch</h3>
          <ul>
            <li><strong>Email:</strong> <a href="mailto:devjangig@gmail.com">devjangig@gmail.com</a></li>
            <li><strong>Phone:</strong> <a href="tel:+911234567890">+91 1234567890</a></li>
            <li><strong>GitHub:</strong> <a href="https://github.com/dev9913" target="_blank" rel="noreferrer">github.com/dev9913</a></li> {/* Added rel="noreferrer" */}
            <li><strong>LinkedIn:</strong> <a href="https://www.linkedin.com/in/dev-jangir-a7a8692b9" target="_blank" rel="noreferrer">linkedin.com/in/dev-jangir</a></li> {/* Added rel="noreferrer" */}
          </ul>
        </div>
      </div>
    </section>
  );
};

export default Contact;
